 function initialMode(record,context){const requested=projectRequest(context),state=context?.state||{};if(context?.solar&&(!requested||requested==='solar'))return 'solar';if(context?.compute&&(!requested||requested==='compute'))return 'compute';if(requested==='charge')return 'ftd';if(['solar','compute'].includes(requested))return 'expansion';if(['club','retention'].includes(record?.script))return record.script;if(state.plan||state.planDraft)return 'ftd';if(record?.script==='academy')return 'academy';return 'academy';}
 function clubReadiness(state={},crm={},time=Date.now()){state=state||{};crm=crm||{};if(crm.status==='do_not_contact')return 'do_not_contact';if(crm.callData?.serviceIssue||crm.callData?.clubInterest==='issue')return 'issue';if(crm.callData?.clubInterest==='declined')return 'declined';const f=club.firstFunding(state);if(!f||f.receiptChecked!==true)return 'no_funding';if(!funnel.firstWithdrawal(state,time))return 'no_withdrawal';return 'ready';}
